    g, d = 0, len(t) - 1
    while g < d:
        s = t[g] + t[d]
        if s == cible:
            return g, d
        if s < cible:
            g += 1
        else:
            d -= 1
    return None

def plus_longue_sans_doublon(s):
    vus, g, meilleur = set(), 0, 0
    for d, c in enumerate(s):
        while c in vus:
            vus.remove(s[g])
            g += 1
        vus.add(c)
        meilleur = max(meilleur, d - g + 1)
    return meilleur

