from collections import deque

def distances(graphe, depart):
    dist = {depart: 0}
    file = deque([depart])
    while file:
        n = file.pop()
        for v in graphe[n]:
            if v not in dist:
                dist[v] = dist[n] + 1
                file.append(v)
    return dist
